/* generated by extract.py from ../../Core/DSP/Instruments/Alkaline/AlkalineControl.c */
/*
 * AlkalineControl.c - TB-303 control path at control rate (S093 P0; Tier 1
 * and Tier 2 reductions since S093 P3, S093_P2 §3A).
 * See AlkalineControl.h. Equations: S092_P6_DSP_EQUATIONS.md §4.1-§4.4,
 * §5.2 (prewarp); reference code: tools/alkaline/alk_model.py (expo_current,
 * Meg, AccentNet, prewarp with fast=True).
 */
#include <math.h>



/* ---- circuit values ([SN] p5 unless stated; S092 P6 §4 tables) ---- */
#define V12        12.0f
#define V561       3.263f          /* Q9's node at rest (P4 §3.1) */
#define VBE11_CAL  0.5279f         /* Q11 Vbe at 7.375 uA */
#define I_CAL      7.375e-6f
#define BETA11     240.0f
#define R47        10e3f
#define R61        10e3f
#define R63        220e3f
#define R71        2.2e3f
#define R72        100e3f
#define R73        100e3f
#define R46        47e3f
#define R119       47e3f
#define R120       22e3f
#define C13F       1e-6f
#define C36F       0.033e-6f
#define TM3        152.74e3f       /* P4 calibration */
#define VR         50e3f           /* VR3, VR4b, VR5, VR7 */
#define VD24       0.48f
#define R_4066     250.0f
#define VT         0.02585f
#define ND_VT      (1.752f * VT)   /* 1N4148 n Vt */
#define IS_D       2.52e-9f
#define I_R117     ((5.333f - 1.02f) / 22e3f)

float alk_taper(const float r)
{
	return (alk_exp2f(4.0f * r) - 1.0f) * (1.0f / 15.0f);
}

/* ---- §4.1 expo converter (Q9/Q10/Q11) ----
 * T1-4: ALK_EXPO_PASSES fixed-point passes on Q11's Vbe from the last block's
 * current (iPrev); a pass contracts a small error by about
 * VT / (V_th3 - V561 - V_be), 0.01, but a strike moves the current by octaves
 * in one block, which one pass leaves 20-30 cents off at the peak (S093 P3). */
#ifndef ALK_EXPO_PASSES
#define ALK_EXPO_PASSES 2u
#endif
float alk_expoCurrent(const float cut, const float env, const float n53,
                      const float vW4, const float iPrev, float *dv)
{
	const float r3 = VR * alk_taper(cut);
	const float vth3 = V561 + (V12 - V561) * (R47 + r3) / (R47 + VR);
	const float rth3 = (VR - r3) * (R47 + r3) / (R47 + VR);
	const float r5 = VR * alk_taper(env);
	const float vth5 = V561 + (n53 - V561) * (R61 + r5) / (R61 + VR);
	const float rth5 = (R61 + r5) * (VR - r5) / (R61 + VR);
	/* S093 P3: 1/(R63 + rth5) and 1/(rth3 + TM3 + R73) from one division */
	const float a5 = R63 + rth5, a3 = rth3 + TM3 + R73;
	const float iq = 1.0f / (a5 * a3);
	const float g5 = iq * a3;
	const float ir = iq * a5;
	const float g4 = 1.0f / R72;
	const float d = ((vth5 - V561) * g5 + (vW4 - V561) * g4)
	              / (1.0f / R71 + g5 + g4);
	const float e = alk_expf(d * (1.0f / VT));
	const float ge = e / (1.0f + e * (1.0f / BETA11));
	float i = fmaxf(iPrev, 1e-12f);
	uint8_t n;

	for (n = 0u; n < ALK_EXPO_PASSES; n++) {
		const float vbe = VBE11_CAL + VT * alk_lnf(i * (1.0f / I_CAL));

		i = fmaxf((vth3 - (V561 + vbe)) * ir, 1e-12f) * ge;
	}
	*dv = d;
	return i;
}

/* ---- §4.2 MEG ---- */
void alkMeg_init(AlkMeg *m)
{
	m->v = ALK_MEG_V_REST;
	m->strikeLeft = 0.0f;
	m->i = 0.0f;
}

void alkMeg_trigger(AlkMeg *m)
{
	m->strikeLeft = ALK_MEG_T_STRIKE_S;
}

float alkMeg_n53(const AlkMeg *m)
{
	/* softplus as max(x, 0) + ln(1 + e^-|x|): no overflow, no branch */
	const float x = (m->v - ALK_MEG_DROP) * (1.0f / ALK_MEG_SOFT);
	const float sp = fmaxf(x, 0.0f) + alk_lnf(1.0f + alk_expf(-fabsf(x)));

	return ALK_MEG_V53_MIN + ALK_MEG_SOFT * sp;
}

/*
 * T1-2: the discharge through R138 + VR6 (or the 4066 on ACCENT) into the
 * D28 / D27 + D26 stack, whose voltage vy follows its current i:
 * r i + vy(i) = v. One Newton step from the last block's current (four
 * fixed-point passes from a cold start in S093 P0: the fixed point stops
 * contracting near the floor, where Newton does not); vy at the new current
 * by its tangent. A strike leaves the cold estimate (v - 1.3)/r for the
 * first block after it.
 * S093 P6: the decay range is stretched, -20 % at decay 0 and +50 % at
 * decay 1 (user): r = ALK_MEG_R_MIN + ALK_MEG_R_SPAN x taper (fitted,
 * fit_meg_range.py). The accent branch keeps 68 k + 250 R, so an accented
 * note's decay is the 303's.
 */
float alkMeg_step(AlkMeg *m, const float decay, const uint8_t accent)
{
	const float r = accent ? (68e3f + R_4066)
	                       : (ALK_MEG_R_MIN + ALK_MEG_R_SPAN * alk_taper(decay));

	if (m->strikeLeft > 0.0f) {
		m->v = ALK_MEG_V_PEAK;
		m->strikeLeft -= ALK_DT;
		m->i = (ALK_MEG_V_PEAK - 1.3f) / r;
	} else {
		const float i = fmaxf(m->i, 0.0f);
		/* S093 P3: 1/r, 1/(I117 + i + Is), 1/(i + Is) from one division */
		const float pa = I_R117 + i + IS_D, pb = i + IS_D;
		const float iq = 1.0f / (r * pa * pb);
		const float ir = iq * pa * pb;
		const float ga = iq * r * pb;                  /* d ln(a)/di */
		const float gb = iq * r * pa;                  /* d ln(b)/di */
		const float vy = ND_VT * (2.0f * alk_lnf((I_R117 + i) * (1.0f / IS_D) + 1.0f)
		                          + alk_lnf(i * (1.0f / IS_D) + 1.0f));
		const float dvy = ND_VT * (2.0f * ga + gb);
		const float inew = fmaxf(i - (r * i + vy - m->v) / (r + dvy), 0.0f);
		const float vyn = vy + dvy * (inew - i);

		m->i = inew;
		m->v = vyn + (m->v - vyn) * alk_expf(-ALK_DT * 1e6f * ir);   /* C62 = 1 uF */
	}
	return alkMeg_n53(m);
}

/* ---- §4.3 accent network ---- */
void alkAcc_init(AlkAccentNet *a)
{
	a->v13 = ALK_ACC_V13_REST;
	a->v36 = 0.0f;
	a->d24 = 0u;
	a->d27 = 0u;
}

/*
 * T1-1 / T2-3: the backward-Euler nodal solve over (W7, P, W, V13, V36) of
 * S092 P6 §4.3, written out for its fixed shape: V13 (row 3), V36 (row 4)
 * and P (row 1) are eliminated, leaving a 2 x 2 in (W7, W), solved by
 * Cramer's rule. Returns the solution and whether the diode states it was
 * solved with are consistent with it.
 */
typedef struct { float w7, w, v13, v36; uint8_t d24, d27, ok; } AlkAccSol;

static inline AlkAccSol alk_accSolve(const AlkAccentNet *a, const uint8_t d24,
                                     const uint8_t d27, const float ga7, const float gb7,
                                     const float gra, const float grb, const float n53,
                                     const float v134)
{
	const float g13 = C13F / ALK_DT, g36 = C36F / ALK_DT;
	const float g119 = 1.0f / R119;
	const float g46 = d24 ? 1.0f / R46 : 0.0f;
	const float g120 = d27 ? 1.0f / R120 : 0.0f;
	/* S093 P3: kP, k3, k4 from one division */
	const float sP = g46 + gra, s3 = grb + g13, s4 = g119 + g36 + g120;
	const float iq = 1.0f / (sP * s3 * s4);
	const float kP = iq * s3 * s4, k3 = iq * sP * s4, k4 = iq * sP * s3;
	/* row 1: P = a1 + c1 W7 + d1 W */
	const float a1 = -kP * g46 * VD24, c1 = kP * g46, d1 = kP * gra;
	/* row 3: V13 = a3 + b3 W */
	const float a3 = k3 * g13 * a->v13, b3 = k3 * grb;
	/* row 4: V36 = a4 + b4 W7 */
	const float a4 = k4 * (g36 * a->v36 + g120 * ALK_ACC_VD27), b4 = k4 * g119;
	/* rows 0 and 2 in (W7, W) */
	const float A00 = ga7 + gb7 + g46 + g119 - g46 * c1 - g119 * b4;
	const float A01 = -g46 * d1;
	const float A10 = -gra * c1;
	const float A11 = gra + grb + (1.0f / R72) - gra * d1 - grb * b3;
	const float B0 = n53 * gb7 + g46 * VD24 + g46 * a1 + g119 * a4;
	const float B1 = v134 * (1.0f / R72) + gra * a1 + grb * a3;
	const float idet = 1.0f / (A00 * A11 - A01 * A10);
	AlkAccSol x;

	x.w7 = (B0 * A11 - A01 * B1) * idet;
	x.w = (A00 * B1 - A10 * B0) * idet;
	x.v13 = a3 + b3 * x.w;
	x.v36 = a4 + b4 * x.w7;
	/* the states this solution implies */
	x.d24 = (uint8_t)(x.w7 - VD24 - (a1 + c1 * x.w7 + d1 * x.w) >= 0.0f);
	x.d27 = (uint8_t)(x.v36 - ALK_ACC_VD27 >= 0.0f);
	x.ok = (uint8_t)(x.d24 == d24 && x.d27 == d27);
	return x;
}

/*
 * The accent step. ALK_ACC_SOLVES selects the form (constant cost in each):
 *   1  T2-3: one solve with the states the last block's solution implied
 *      (one block of switching lag, 0.73 ms);
 *   2  T1-1: that solve; then the states its own solution implies, solved
 *      again; the first consistent of the two is kept (else the second);
 *   4  the S093 P0 / alk_model.py rule: all four states in the order
 *      (1,1) (1,0) (0,1) (0,0), the first consistent kept (else the last).
 */
/* S093 P3: 1 (T2-3), accepted by the user after the listening test
 * (tools/alkaline/listen_bc.py): validate.py --fast V3c puts its accent-run
 * peaks 1.9-2.8 % below the S093 P0 form (closer to SPICE); it saves about 70
 * instructions and 2 VDIV per block against 2 (T1-1). */
#ifndef ALK_ACC_SOLVES
#define ALK_ACC_SOLVES 1
#endif
void alkAcc_step(AlkAccentNet *a, const uint8_t accent, const float accKnob,
                 const float res, const float n53, const float v134,
                 float *vW4, float *iAcc)
{
	const float ra7 = fmaxf(VR * accKnob, 1.0f);
	const float rb7 = fmaxf(VR * (1.0f - accKnob), 1.0f) + (accent ? R_4066 : 1e12f);
	const float ra = fmaxf(VR * res, 1.0f);
	const float rb = fmaxf(VR * (1.0f - res), 1.0f);
	/* S093 P3: the four knob conductances from one division */
	const float p12 = ra7 * rb7, p34 = ra * rb;
	const float iq = 1.0f / (p12 * p34);
	const float ga7 = iq * rb7 * p34, gb7 = iq * ra7 * p34;
	const float gra = iq * p12 * rb, grb = iq * p12 * ra;
	AlkAccSol x;

#if ALK_ACC_SOLVES == 4
	{
		static const uint8_t combos[4][2] = { {1u, 1u}, {1u, 0u}, {0u, 1u}, {0u, 0u} };
		uint8_t n, found = 0u;

		for (n = 0u; n < 4u; n++) {
			const AlkAccSol y = alk_accSolve(a, combos[n][0], combos[n][1], ga7, gb7,
			                                 gra, grb, n53, v134);
			if (!found && (y.ok || n == 3u)) {
				x = y;
				found = 1u;
			}
		}
	}
#elif ALK_ACC_SOLVES == 2
	{
		const AlkAccSol y = alk_accSolve(a, a->d24, a->d27, ga7, gb7, gra, grb, n53, v134);
		const AlkAccSol z = alk_accSolve(a, y.d24, y.d27, ga7, gb7, gra, grb, n53, v134);

		x = y.ok ? y : z;
	}
#else
	x = alk_accSolve(a, a->d24, a->d27, ga7, gb7, gra, grb, n53, v134);
#endif
	a->v13 = x.v13;
	a->v36 = x.v36;
	a->d24 = x.d24;
	a->d27 = x.d27;
	*vW4 = x.w;
	*iAcc = fmaxf(0.0f, (x.v36 - ALK_ACC_VD27) * (1.0f / R120));
}

/* ---- §4.4 VEG ---- */
void alkVeg_init(AlkVeg *g)
{
	g->v = 12.0f - 1e-3f;
	g->delayLeft = 0.0f;
	g->attLeft = 0.0f;
	g->keep = alkVegAttack[0].keep;   /* the 0.70 ms attack until a trigger sets one */
}

void alkVeg_trigger(AlkVeg *g, const float attack)
{
	/* the knob over the table points; the clamp keeps a modulated value in
	 * range, and k stops one short of the end so k + 1 is a point */
	const float p = fminf(fmaxf(attack, 0.0f), 1.0f) * (float)(ALK_VEG_ATT_POINTS - 1u);
	uint32_t k = (uint32_t)p;
	float f;

	if (k > ALK_VEG_ATT_POINTS - 2u)
		k = ALK_VEG_ATT_POINTS - 2u;
	f = p - (float)k;
	{
		const AlkVegAttack *a = &alkVegAttack[k];
		const AlkVegAttack *b = &alkVegAttack[k + 1u];

		/* linear in the knob between the fitted trigger widths; at attack 0
		 * f is 0, so each is point 0 exactly: the former delay, 8 tau and
		 * the folded exp(-ALK_DT / tau) */
		g->delayLeft = a->delay + f * (b->delay - a->delay);
		g->attLeft = a->len + f * (b->len - a->len);
		g->keep = a->keep + f * (b->keep - a->keep);
	}
}

float alkVeg_step(AlkVeg *g, const uint8_t gate)
{
	if (g->delayLeft > 0.0f) {
		g->delayLeft -= ALK_DT;
	} else if (g->attLeft > 0.0f) {
		/* S093 P6: this note's factor (alkVeg_trigger()); was the folded
		 * expf(-ALK_DT / ALK_VEG_TAU_ATT_S), which is alkVegAttack[0].keep */
		g->v *= g->keep;
		g->attLeft -= ALK_DT;
	}
	g->v = ALK_VEG_V_REC + (g->v - ALK_VEG_V_REC) * expf(-ALK_DT / ALK_VEG_TAU_REC_S);
	{
		float p = (g->v - ALK_VEG_V0) * ALK_VEG_DV_INV;
		int32_t k;
		float i;

		p = fminf(fmaxf(p, 0.0f), (float)(ALK_VEG_POINTS - 1u));
		k = (int32_t)p;
		if (k > (int32_t)ALK_VEG_POINTS - 2)
			k = (int32_t)ALK_VEG_POINTS - 2;
		i = alkVegCurrent[k] + (p - (float)k) * (alkVegCurrent[k + 1] - alkVegCurrent[k]);
		return gate ? i : 0.0f;
	}
}

/* ---- §5.2 TPT prewarp: the factor on the ladder current ----
 * T1-5: tan(th)/th = (945 - 105 th^2 + th^4) / (945 - 420 th^2 + 15 th^4)
 * (the [5/4] tan Pade over th; th <= 1.3, where it is within 1e-5).
 * S093 P6: alkPrewarpC is indexed by the knob over ALK_PREWARP_POINTS (16:
 * k_eff 0, 0.1 .. 1.5, held at c(1) above 1), not by a fixed 11 points. */
float alk_prewarp(const float iLad, const float res)
{
	/* the knob over the table: p = 15 x knob = 10 x k_eff, the same point
	 * and fraction as the former 10 x k for every stock setting */
	float p = fminf(fmaxf(res, 0.0f), 1.0f) * (float)(ALK_PREWARP_POINTS - 1u);
	int32_t k = (int32_t)p;
	float c, th, s;

	if (k > (int32_t)ALK_PREWARP_POINTS - 2)
		k = (int32_t)ALK_PREWARP_POINTS - 2;
	c = alkPrewarpC[k] + (p - (float)k) * (alkPrewarpC[k + 1] - alkPrewarpC[k]);
	/* theta = c w1 / (2 fs), w1 = I / (4 Vt C19) */
	th = fminf(c * iLad * (1.0f / (4.0f * VT * 33e-9f)) / (2.0f * 44108.0f), 1.3f);
	s = th * th;
	return (945.0f + s * (-105.0f + s)) / (945.0f + s * (-420.0f + 15.0f * s));
}

